import { test, expect } from '@playwright/test'

/**
 * Authentication Flow E2E Tests
 * Comprehensive testing of user authentication workflows
 */

test.describe('Authentication Flows', () => {
  test.beforeEach(async ({ page }) => {
    // Start each test from the auth page
    await page.goto('/auth')
    await page.waitForLoadState('networkidle')
  })

  test.describe('Sign Up Flow', () => {
    test('displays sign up form correctly', async ({ page }) => {
      // Verify page title
      await expect(page).toHaveTitle(/CoachFlow.*Auth/i)

      // Check sign up form elements are visible
      await expect(page.locator('h1, h2')).toContainText(/sign up|create account/i)
      await expect(page.locator('input[type="email"]')).toBeVisible()
      await expect(page.locator('input[type="password"]')).toBeVisible()
      await expect(page.locator('button[type="submit"]')).toBeVisible()

      // Check role selection if present
      const roleSelector = page.locator('select[name="role"], input[name="role"]')
      if (await roleSelector.count() > 0) {
        await expect(roleSelector).toBeVisible()
      }
    })

    test('validates required fields', async ({ page }) => {
      // Try to submit empty form
      await page.click('button[type="submit"]')

      // Should show validation errors
      await expect(page.locator('text=email.*required', { timeout: 5000 })).toBeVisible()
      await expect(page.locator('text=password.*required')).toBeVisible()
    })

    test('validates email format', async ({ page }) => {
      // Enter invalid email
      await page.fill('input[type="email"]', 'invalid-email-format')
      await page.fill('input[type="password"]', 'ValidPassword123!')
      await page.click('button[type="submit"]')

      // Should show email format error
      await expect(page.locator('text=invalid.*email|email.*invalid')).toBeVisible()
    })

import { defineConfig, devices } from '@playwright/test'

export default defineConfig({
  testDir: './src/test/e2e',
  timeout: 30 * 1000,
  expect: {
    timeout: 5000
  },
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: [
    ['html'],
    ['json', { outputFile: 'playwright-report/results.json' }]
  ],
  use: {
    baseURL: 'http://localhost:3000',
    trace: 'on-first-retry',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    actionTimeout: 10000,
    navigationTimeout: 30000
  },

  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] }
    },
    {
      name: 'firefox',
      use: { ...devices['Desktop Firefox'] }
    },
    {
      name: 'webkit',
      use: { ...devices['Desktop Safari'] }
    },
    {
      name: 'Mobile Chrome',
      use: { ...devices['Pixel 5'] }
    },
    {
      name: 'Mobile Safari',
      use: { ...devices['iPhone 12'] }
    }
  ],

  webServer: {
    command: 'npm run dev',
    url: 'http://localhost:3000',
    reuseExistingServer: !process.env.CI,
    timeout: 120000
  },

  outputDir: 'test-results',

  /* Global setup and teardown */
  globalSetup: './src/test/e2e/global-setup.ts',
  globalTeardown: './src/test/e2e/global-teardown.ts'
})

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // Security headers to prevent XSS, clickjacking, and other attacks
  async headers() {
    return [
      {
        source: '/(.*)',
        headers: [
          // Prevent XSS attacks
          {
            key: 'X-Content-Type-Options',
            value: 'nosniff'
          },
          // Prevent clickjacking attacks
          {
            key: 'X-Frame-Options',
            value: 'DENY'
          },
          // Force HTTPS
          {
            key: 'Strict-Transport-Security',
            value: 'max-age=63072000; includeSubDomains; preload'
          },
          // Control referrer information
          {
            key: 'Referrer-Policy',
            value: 'strict-origin-when-cross-origin'
          },
          // Permissions policy
          {
            key: 'Permissions-Policy',
            value: 'camera=(), microphone=(), geolocation=(), payment=(), usb=(), bluetooth=()'
          },
          // Content Security Policy - Strict but allows necessary resources
          {
            key: 'Content-Security-Policy',
            value: [
              "default-src 'self'",
              "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://js.stripe.com https://cdn.jsdelivr.net",
              "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
              "font-src 'self' https://fonts.gstatic.com",
              "img-src 'self' data: https: blob:",
              "connect-src 'self' https://*.supabase.co https://api.openai.com wss://*.supabase.co",
              "frame-src 'none'",
              "object-src 'none'",
              "base-uri 'self'",
              "form-action 'self'",
              "upgrade-insecure-requests"
            ].join('; ')
          }
        ]
      }
    ]
  },

  // Additional security configurations
  poweredByHeader: false, // Remove X-Powered-By header

  // Image optimization configuration
  images: {
    domains: ['images.unsplash.com', 'via.placeholder.com'],
    formats: ['image/avif', 'image/webp'],
    minimumCacheTTL: 60 * 60 * 24 * 30, // 30 days
    dangerouslyAllowSVG: false,
    deviceSizes: [640, 750, 828, 1080, 1200, 1920, 2048, 3840],
    imageSizes: [16, 32, 48, 64, 96, 128, 256, 384]
  },

  // Optimize for performance and security
  experimental: {
    optimizePackageImports: ['lucide-react', 'framer-motion']
  }
};

export default nextConfig;

