export default function CoachListingsPage() {
  const router = useRouter()
  const supabase = createClient()
  const [user, setUser] = useState<any>(null)
  const [profile, setProfile] = useState<any>(null)
  const [listings, setListings] = useState<any[]>([])
  const [existingApplications, setExistingApplications] = useState<any[]>([])
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    async function loadData() {
      try {
        // Get current user
        const { data: { user: currentUser } } = await supabase.auth.getUser()
        if (!currentUser) {
          router.push('/auth/sign-in')
          return
        }

        // Check if user is a coach
        const { data: userData } = await supabase
          .from('users')
          .select('role')
          .eq('id', currentUser.id)
          .single()

        if (userData?.role !== 'coach') {
          router.push('/')
          return
        }

        setUser(currentUser)

        // Get coach profile for verification check
        const { data: profileData } = await supabase
          .from('coach_profiles')
          .select('wwcc_number, insurance_url, first_aid_url, suburbs')
          .eq('user_id', currentUser.id)
          .single()

        setProfile(profileData)

        // If verified, get listings and applications
        const isVerified = profileData?.wwcc_number && profileData?.insurance_url && profileData?.first_aid_url
        if (isVerified) {
          // Get active listings
          const { data: listingsData } = await supabase
            .from('listings')
            .select(`
              *,
              org:users!listings_org_id_fkey(
                org_profiles!inner(
                  org_name
                )
              ),
              applications!inner(count)
            `)
            .eq('status', 'active')
            .order('created_at', { ascending: false })

          // Get coach's existing applications
          const { data: applicationsData } = await supabase
            .from('applications')
            .select('listing_id')
            .eq('coach_id', currentUser.id)

          setListings(listingsData || [])
          setExistingApplications(applicationsData || [])
        }
      } catch (error) {
        console.error('Error loading data:', error)
      } finally {
        setIsLoading(false)
      }
    }

    loadData()
  }, [router, supabase])

  const isVerified = profile?.wwcc_number && profile?.insurance_url && profile?.first_aid_url

